**For TypeScript**:

Create `src/server.ts`:

```typescript
import { Server } from "@modelcontextprotocol/sdk/server/index.js"
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js"
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js"
import { Tools, ToolSchemas } from "./tools.js"
import { PluginClient } from "./client.js" // HTTP/API client

const server = new Server(
  {
    name: "[plugin]-adapter",
    version: "0.1.0",
  },
  {
    capabilities: {
      tools: {},
    },
  }
)

// Initialize plugin client
const client = new PluginClient({
  baseUrl: process.env.PLUGIN_BASE_URL || "[default]",
  apiKey: process.env.PLUGIN_API_KEY,
  timeout: parseInt(process.env.PLUGIN_TIMEOUT || "30000"),
})

// List tools handler
server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: Tools,
}))

// Call tool handler
server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params

  // Validate parameters
  const schema = ToolSchemas[name]
  if (!schema) {
    throw new Error(`Unknown tool: ${name}`)
  }

  const validatedArgs = schema.parse(args)

  // Route to appropriate handler
  switch (name) {
    case "[plugin]_[action]":
      return await handle_action(validatedArgs)
    // ... more cases
    default:
      throw new Error(`Unimplemented tool: ${name}`)
  }
})

// Tool implementations
async function handle_action(params: any) {
  try {
    // Call plugin API/functionality
    const result = await client.performAction(params)

    return {
      content: [
        {
          type: "text",
          text: JSON.stringify(result, null, 2),
        },
      ],
    }
  } catch (error) {
    return {
      content: [
        {
          type: "text",
          text: `Error: ${error.message}`,
        },
      ],
      isError: true,
    }
  }
}

// Start server
async function main() {
  const transport = new StdioServerTransport()
  await server.connect(transport)
  console.error("[plugin] MCP adapter running on stdio")
}

main().catch(console.error)
```

**For Python**:

Create `src/server.py`:

```python
import asyncio
import os
from mcp.server import Server
from mcp.server.stdio import stdio_server
from .tools import TOOLS, ToolNameParams
from .client import PluginClient

app = Server("[plugin]-adapter")

# Initialize plugin client
client = PluginClient(
    base_url=os.getenv("PLUGIN_BASE_URL", "[default]"),
    api_key=os.getenv("PLUGIN_API_KEY"),
    timeout=int(os.getenv("PLUGIN_TIMEOUT", "30")),
)

@app.list_tools()
async def list_tools() -> list:
    return TOOLS

@app.call_tool()
async def call_tool(name: str, arguments: dict):
    """Route tool calls to appropriate handlers"""

    if name == "[plugin]_[action]":
        params = ToolNameParams(**arguments)
        return await handle_action(params)
    # ... more cases
    else:
        raise ValueError(f"Unknown tool: {name}")

# Tool implementations
async def handle_action(params: ToolNameParams) -> dict:
    """Handle [action] tool call"""
    try:
        result = await client.perform_action(
            param1=params.param1,
            param2=params.param2,
        )
        return {
            "content": [
                {
                    "type": "text",
                    "text": str(result),
                }
            ]
        }
    except Exception as e:
        return {
            "content": [
                {
                    "type": "text",
                    "text": f"Error: {str(e)}",
                }
            ],
            "isError": True,
        }

async def main():
    async with stdio_server() as streams:
        await app.run(
            streams[0], streams[1],
            app.create_initialization_options()
        )

if __name__ == "__main__":
    asyncio.run(main())
```

