**For Python** (pytest):

Create `tests/test_tools.py`:
```python
import pytest
from [plugin]_mcp.tools import TOOLS, ToolNameParams
from [plugin]_mcp.server import call_tool
from unittest.mock import AsyncMock, patch

@pytest.mark.asyncio
class TestTools:
    async def test_list_tools(self):
        """Test that all tools are defined"""
        assert len(TOOLS) > 0
        for tool in TOOLS:
            assert tool.name
            assert tool.description

    async def test_tool_name_validation(self):
        """Test parameter validation for tool_name"""
        # Valid params
        valid = ToolNameParams(param1="value", param2=123)
        assert valid.param1 == "value"

        # Invalid params
        with pytest.raises(ValueError):
            ToolNameParams(param1=None)  # Required param

    @patch("[plugin]_mcp.client.PluginClient.perform_action")
    async def test_tool_execution(self, mock_client):
        """Test tool execution with mocked client"""
        mock_client.return_value = {"success": True}

        result = await call_tool(
            "[plugin]_action",
            {"param1": "value"}
        )

        assert result["content"][0]["type"] == "text"
        mock_client.assert_called_once()
